import os,re,json
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
print(sorted(G))
I2,O2=G['Demo pair 2 input'],G['Demo pair 2 output']
I1,O1=G['Demo pair 1 input'],G['Demo pair 1 output']
# check: which shape cells changed?
from collections import Counter
for n,(I,O) in enumerate([(I1,O1),(I2,O2)],1):
    h,w=len(I),len(I[0])
    bg=Counter(x for r in I for x in r).most_common(1)[0][0]
    sh=[c for c in Counter(x for r in I for x in r) if c!=bg][0]
    fr={r for r in range(h) if all(I[r][c]==sh for c in range(w))}
    fc={c for c in range(w) if all(I[r][c]==sh for r in range(h))}
    changed={(r,c) for r in range(h) for c in range(w) if I[r][c]!=O[r][c]}
    online={(r,c) for r in range(h) for c in range(w) if r in fr or c in fc}
    print(n,'bg',bg,'shape',sh,'fullrows',sorted(fr),'fullcols',sorted(fc))
    print(' changed==online?',changed==online, 'changed-outside-online:',sorted(changed-online)[:10])
